// Extracted PSD layers keep their original pixel dimensions and origins.
window.loadIntroParallax=async function(number=2){
 const manifest=await fetch('assets/intro'+number+'/layers.json').then(r=>{if(!r.ok)throw Error('intro PSD layers');return r.json()});
 const assets={};await Promise.all([manifest.background,...manifest.frames.flatMap(f=>[f.a,f.b])].filter(l=>l?.src).map(async l=>{assets[l.src]=await new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>resolve(im);im.onerror=()=>reject(Error(l.src));im.src=l.src})}));
 const defaults={speed:6,interval:.25,duration:2,frames:[{direction:'left',multiplier:.35},{direction:'up',multiplier:.5},{direction:'right',multiplier:.25}]};
 defaults.frames=manifest.frames.map((_,i)=>defaults.frames[i]||defaults.frames[0]);const storageKey=number===2?'peninsula-intro-parallax':'peninsula-intro-parallax-'+number;
 let settings=JSON.parse(JSON.stringify(defaults));try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved){settings.speed=Number(saved.speed)||0;if(saved.duration!==undefined)settings.duration=Number(saved.duration)||2;if(saved.interval!==undefined)settings.interval=Number(saved.interval)||0;settings.frames=defaults.frames.map((f,i)=>({...f,...saved.frames?.[i]}))}}catch{}
 const offsets=manifest.frames.map(()=>({a:0,b:0}));let paused=false,last=null,elapsed=0;
 const vectors={left:[-1,0],right:[1,0],up:[0,-1],down:[0,1]};
 function configure(value){if(value.duration!==undefined)settings.duration=Math.max(.1,Math.min(60,Number(value.duration)||2));if(value.interval!==undefined)settings.interval=Math.max(0,Math.min((settings.duration-.01)/2,Number(value.interval)||0));if(value.speed!==undefined)settings.speed=Math.max(0,Math.min(100,Number(value.speed)||0));settings.interval=Math.min(settings.interval,(settings.duration-.01)/2);if(elapsed>=settings.duration){elapsed=0;offsets.forEach(o=>{o.a=0;o.b=0});last=null}if(value.frames)settings.frames=settings.frames.map((f,i)=>{const n={...f,...value.frames[i]};if(!vectors[n.direction])n.direction='left';n.multiplier=Math.max(-4,Math.min(4,Number(n.multiplier)||0));return n});try{localStorage.setItem(storageKey,JSON.stringify(settings))}catch{}}
 configure(settings);
 function advance(dt){if(paused)return false;let completed=false;dt=Math.max(0,Math.min(.1,dt));let previous=elapsed;elapsed+=dt;if(elapsed>=settings.duration-1e-9){completed=true;elapsed=Math.max(0,elapsed-settings.duration);offsets.forEach(o=>{o.a=0;o.b=0});dt=elapsed;previous=0}manifest.frames.forEach((frame,i)=>{const activeDt=Math.max(0,elapsed-Math.max(previous,i*settings.interval));offsets[i].a+=settings.speed*activeDt;offsets[i].b+=settings.speed*settings.frames[i].multiplier*activeDt});return completed}
 function tick(now,visible=true){const completed=last!==null&&visible?advance((now-last)/1000):false;last=now;return completed}
 function drawLayer(ctx,layer,frame,distance,direction){const [dx,dy]=vectors[direction];ctx.drawImage(assets[layer.src],layer.x+dx*Math.round(distance),layer.y+dy*Math.round(distance))}
 function draw(ctx,x=1,y=1){ctx.save();ctx.imageSmoothingEnabled=false;ctx.translate(x,y);ctx.beginPath();ctx.rect(0,0,manifest.width,manifest.height);ctx.clip();const back=manifest.background;ctx.drawImage(assets[back.src],back.x,back.y);
  manifest.frames.forEach((f,i)=>{if(elapsed+1e-9<i*settings.interval)return;ctx.save();ctx.beginPath();ctx.rect(f.frame.x,f.frame.y,f.frame.w,f.frame.h);ctx.clip();drawLayer(ctx,f.b,f.frame,offsets[i].b,settings.frames[i].direction);drawLayer(ctx,f.a,f.frame,offsets[i].a,settings.frames[i].direction);ctx.restore()});ctx.restore();
 }
 return{draw,tick,advance,configure,reset(){offsets.forEach(o=>{o.a=0;o.b=0});elapsed=0;last=null},setPaused(value){paused=!!value},snapshot:()=>({settings:JSON.parse(JSON.stringify(settings)),offsets:offsets.map(o=>({...o})),number,paused,elapsed,cycleDuration:settings.duration,manifest})};
};
window.buildParallaxControls=function(host,game,redraw){const indices=game.snapshot().manifest.frames.map((_,i)=>i+1);host.innerHTML='<h2>Параллакс заставки '+game.snapshot().number+'</h2><label class="number">Длительность цикла, с<input id="parallax-duration" type="number" min="0.1" max="60" step="0.1"></label><label class="number">Интервал появления, с<input id="parallax-interval" type="number" min="0" step="0.05"></label><label class="number">Общая скорость, px/с<input id="parallax-speed" type="number" min="0" max="100" step="0.5"></label>'+indices.map(i=>'<fieldset><legend>Фрейм '+i+'</legend><label class="number">Направление<select id="parallax-direction-'+i+'"><option value="left">Влево</option><option value="right">Вправо</option><option value="up">Вверх</option><option value="down">Вниз</option></select></label><label class="number">Множитель заднего слоя B<input id="parallax-factor-'+i+'" type="number" min="-4" max="4" step="0.05"></label></fieldset>').join('')+'<div class="parallax-actions"><button id="parallax-pause">Пауза</button><button id="parallax-reset">В начало</button></div>';
 const number=game.snapshot().number;host.innerHTML=host.innerHTML.replace(/id="parallax-/g,'id="intro'+number+'-parallax-');const find=selector=>host.querySelector(selector.replace('#parallax-','#intro'+number+'-parallax-'));
 const sync=()=>{const s=game.snapshot().settings;find('#parallax-duration').value=s.duration;find('#parallax-interval').max=(s.duration-.01)/2;find('#parallax-interval').value=s.interval;find('#parallax-speed').value=s.speed;s.frames.forEach((f,i)=>{find('#parallax-direction-'+(i+1)).value=f.direction;find('#parallax-factor-'+(i+1)).value=f.multiplier})};
 const update=()=>{game.configure({duration:find('#parallax-duration').value,interval:find('#parallax-interval').value,speed:find('#parallax-speed').value,frames:indices.map(i=>({direction:find('#parallax-direction-'+i).value,multiplier:find('#parallax-factor-'+i).value}))});sync();redraw()};host.querySelectorAll('input,select').forEach(e=>e.addEventListener('input',update));find('#parallax-pause').onclick=e=>{game.setPaused(!game.snapshot().paused);e.currentTarget.textContent=game.snapshot().paused?'Продолжить':'Пауза';redraw()};find('#parallax-reset').onclick=()=>{game.reset();redraw()};sync();
};
